<?php
namespace Jugendtraining\Component\Jugendtraining\Site\Controller;\defined('_JEXEC') or die;use Joomla\CMS\Factory;use Joomla\CMS\Language\Text;use Joomla\CMS\MVC\Controller\BaseController;use Joomla\CMS\Router\Route;use Joomla\CMS\Session\Session;use Jugendtraining\Component\Jugendtraining\Site\Service\SelfCheckinService;final class SelfcheckinController extends BaseController{public function checkin():void{Session::checkToken() or jexit('JINVALID_TOKEN');$app=Factory::getApplication();try{$distance=(new SelfCheckinService())->checkin($app->input->post->getInt('session_id'),$app->input->post->getFloat('latitude'),$app->input->post->getFloat('longitude'));$app->enqueueMessage(Text::sprintf('COM_JUGENDTRAINING_SELF_CHECKIN_SUCCESS',round($distance)),'success');}catch(\Throwable$e){$m=$e->getMessage();if(str_starts_with($m,'COM_JUGENDTRAINING_'))$m=Text::_($m);$app->enqueueMessage($m,'error');}$this->setRedirect(Route::_('index.php?option=com_jugendtraining&view=selfcheckin',false));}}
